oldered":false}}],"BreadBoard":[{"x":419.53125,"y":195,"tx":315,"ty":-73,"id":1593795986033}],"ServoMotor":[{"x":76.53125,"y":346,"tx":-5,"ty":-137,"id":1593796008196}],"PotentioMeter":[{"x":641.53125,"y":55,"tx":-27,"ty":-40,"id":1593796000275,"data":{"value":0}}],"ArduinoUno":[{"x":369.53125,"y":288,"tx":-196,"ty":-175,"id":1593795977808,"data":{"name":"Arduino UNO R3 1","code":"#include <Servo.h>\\n\\nServo myServo;  // create servo object to control a servo\\n\\nvoid setup() {\\n  // initialize serial communication at 9600 bits per second:\\n  Serial.begin(9600);\\n  \\n  myServo.attach(9);  // attaches the servo on pin 9 to the servo object\\n}\\n\\nvoid loop() {\\n  // reads the value of the potentiometer (value between 0 and 1023)\\n  int analogValue = analogRead(A0);\\n\\n  // scales it to use it with the servo (value between 0 and 180)\\n  int angle = map(analogValue, 0, 1023, 0, 180);\\n\\n  // sets the servo position according to the scaled value\\n  myServo.write(angle); \\n\\n  // print out the value\\n  Serial.print(\\"Analog: \\");\\n  Serial.print(analogValue);\\n  Serial.print(\\", Angle: \\");\\n  Serial.println(angle);\\n  delay(100);\\n}\\n"}}]}	Arduino-Servo Motor controlled by Potentiometer		circuit_images_esim/f092a5e8-ef9a-4496-bb29-b75915a69b7b.png	t	2021-08-19 12:43:58.572+00	t
